{
  "research_concepts": [
    "lineup changes",
    "offensive five",
    "shot mix",
    "personnel effects",
    "shot type distribution",
    "validation of lineup detection design"
  ],
  "methodological_questions": [
    "causal identification using lineup changes",
    "endogeneity of substitutions and confounding by game state",
    "sample size and power for specific lineup pairs",
    "multinomial comparison of shot mix distributions",
    "play-type label noise and its impact",
    "multiple testing across many lineups and shot categories",
    "control for opponent lineup and situation"
  ],
  "historical_evidence": [
    {
      "id": "FAM:SF-TMP-009",
      "status_as_recorded": "artifact",
      "finding": "PULL_UP exposure effect shrinks dramatically when removing lineup FE (from -0.0255 to -0.0063) and a same-shooter placebo on other play types gives -0.0071/-0.0075, indicating shooter‑level confound rather than true defensive adaptation."
    },
    {
      "id": "FAM:SF-APPA-005",
      "status_as_recorded": "untestable",
      "finding": "In-game defensive scheme changes appear near‑uniform across bins, likely because the inferred labels cannot separate real defensive adjustment from offense execution differences; transition matrices near‑uniform consistent with label noise."
    },
    {
      "id": "FAM:SF38",
      "status_as_recorded": "inconclusive",
      "finding": "Overall within‑game exposure slope is not significant, only PULL_UP survives Holm correction after separate testing; limited by insufficient exposure, play‑type classification error, and low measurement reliability."
    },
    {
      "id": "FAM:SF-TMP-016",
      "status_as_recorded": "untestable",
      "finding": "Team heterogeneity in halftime play‑type adaptation is not reliable: split‑half r = -0.026 for adaptation slope and +0.067 for persistence slope, with true‑heterogeneity variance not exceeding sampling noise."
    },
    {
      "id": "FAM:SF34",
      "status_as_recorded": "inconclusive",
      "finding": "When opponent has no big, offenses increase drives (+0.82pp, SE 0.25) and post‑ups, decrease three‑point attempts (-1.79pp, SE 0.31), but rim share change is negligible (+0.12pp, t=0.4); overall PPP shift small (t=1.1)."
    },
    {
      "id": "FAM:SF-TMP-023",
      "status_as_recorded": "not a hypothesis test",
      "finding": "After a timeout, POST_UP share rises by 2.41pp (t=18.7), SPOT_UP by 2.33pp (t=12.9); half‑court PPP changes by -0.0105 (t=-1.89). Descriptive only, no inferential testing."
    },
    {
      "id": "FAM:SF-APPM-021",
      "status_as_recorded": "not a hypothesis test",
      "finding": "Play‑type mix shifts at halftime and in crunch (e.g., OTHER +2.2–2.5pp, PULL_UP +1.2pp), and after runs; but no significance tests and the OTHER category is known to be noisy."
    },
    {
      "id": "FAM:SF-APPS-058",
      "status_as_recorded": "untestable",
      "finding": "Confident on‑ball defensive scheme labels obtained for only 14.9% (DET) and 3.3% (ORL) of possessions; NBA matchups feed did not populate switches_on. Gate failed due to extreme label sparsity."
    },
    {
      "id": "FAM:SF-PAP-050",
      "status_as_recorded": "inconclusive",
      "finding": "Team play‑type mix after a player’s absence was nearly identical to the pre‑absence mix over n=148 spells; paper reports no numeric table and no confidence intervals."
    },
    {
      "id": "FAM:SF-PAP-009",
      "status_as_recorded": "supported",
      "finding": "Lineup coverage (≥1 organizer, shaper, terminal) is only weakly correlated with talent (|ρ|=0.042) and the auxiliary model R²=0.203, confirming coverage is separable; feasibility gate passed."
    }
  ],
  "failed_approaches": [
    {
      "id": "FAM:SF-TMP-009",
      "what_failed": "Using lineup fixed effects without adequate control for shooter‑level confounds led to an artifact (exposure‑effect slope disappeared when lineup FE were removed).",
      "why": "C_artifact: apparent effect produced by a construction, selection, or labelling flaw (shooter‑level confound)."
    },
    {
      "id": "FAM:SF-APPA-005",
      "what_failed": "Inferred defensive scheme labels from play‑by‑play could not distinguish true tactical adjustment, making the question untestable.",
      "why": "A_unanswerable: label or classification error; near‑uniform transition matrices consistent with noise."
    },
    {
      "id": "FAM:SF-TMP-016",
      "what_failed": "Trying to measure reliable team‑level heterogeneity in halftime adaptation failed because measurement reliability was too low.",
      "why": "A_unanswerable: split‑half r ≈ 0, true‑variance ratio not different from null."
    },
    {
      "id": "FAM:SF-APPS-058",
      "what_failed": "Using NBA matchup fields to label on‑ball defensive coverage gave a labelling rate too low for meaningful analysis.",
      "why": "A_unanswerable: label or classification error plus small sample (only 3–15% labels)."
    }
  ],
  "evidence_establishes": [
    "Play‑type mix can shift after timeouts (SF-TMP-023) and when the opponent’s rim protector is off the floor (SF34), indicating the data can capture tactical shot‑mix responses.",
    "Play‑type mix was nearly unchanged after a single player’s absence (SF-PAP-050), though this absence study was small and inconclusive.",
    "Observed lineup‑level effects can be artifacts driven by shooter‑level confounds if lineup fixed effects are not handled carefully (SF-TMP-009).",
    "Defensive‑scheme labels and play‑type classifications (especially OTHER) introduce noise that may mask true signals (SF-APPA-005, SF-APPM-021, SF-APPS-058).",
    "Measurement reliability of play‑type shares at the team or lineup level can be low, making detection of small differences difficult (SF-TMP-016, SF38).",
    "Lineup‑coverage metrics can be constructed without being dominated by talent (SF-PAP-009), suggesting lineups are not merely proxies for overall skill."
  ],
  "evidence_does_not_establish": [
    "Whether a deliberately changed offensive five (e.g., a single‑player substitution) leads to a statistically detectable shift in the full shot‑type distribution after controlling for game context and opponent.",
    "The expected effect size of a single‑player swap on shot mix after controlling for score, period, and opponent lineup.",
    "That such a shift, if found, is causal rather than due to residual confounding from coach substitution patterns.",
    "The power of any proposed test given the number of distinct lineups, play‑type categories, and multiple‑comparison adjustments."
  ],
  "own_inferences": [
    "With three seasons of play‑by‑play and derived play‑type possessions, it is possible to compare offensive fives that differ by exactly one player, within the same game and opponent stint, and test for systematic differences in shot‑type shares.",
    "The primary threats are confounding (substitutions are correlated with score, rest, opponent, etc.), multiple testing, and noise in the shot‑type labels (especially the OTHER bucket).",
    "If the question is merely ‘does the shot mix change when the five changes’, a very large sample will almost certainly reject a null of no difference because players have distinct shot tendencies; the more interesting question is whether the design can reliably attribute those differences to specific personnel configurations net of confounds.",
    "Without exogenous variation (e.g., injuries), a purely observational comparison will be descriptive rather than causal, but it can still answer whether the design possesses sufficient sensitivity to detect lineup‑driven changes in shot mix."
  ],
  "uncertainties": [
    "The magnitude of the shot‑mix shift caused by swapping one rotation player, after adjusting for score and opponent, is unknown; small shifts may be undetectable.",
    "The appropriate null model (individual‑player‑based shot frequencies vs. lineup‑level model) is not specified, which affects interpretation.",
    "How much label noise in play types (especially the OTHER and generic categories) attenuates the signal and erodes power.",
    "Whether the intended ‘design’ refers to a specific APM decomposition or a simpler lineup‑difference approach; the question statement is ambiguous.",
    "Whether the analysis will use only half‑court possessions, control for shot clock, and exclude garbage time, all of which influence power and inference."
  ],
  "historical_effect": {
    "changed_decision": "no",
    "explanation": "The retrieved evidence did not directly answer whether an offensive‑five change moves shot mix detectably. However, it highlighted critical risks—confounding in lineup‑level analyses, low measurement reliability, and label noise—and showed that play‑type mix can shift in other contexts (timeout, opponent big). These findings are incorporated into risk assessment and design, but they did not alter the fundamental feasibility judgment because the hypothesis was previously untested."
  },
  "testability": {
    "p_testable": 0.75,
    "blocking_constraints": [
      {
        "code": "CONFOUNDING",
        "text": "Substitutions are correlated with score, period, opponent, and rest, which also influence shot mix. Naive comparisons will confound these factors."
      },
      {
        "code": "LABEL_ERROR",
        "text": "Play‑type classification (especially the OTHER category) is noisy, reducing sensitivity and potentially creating spurious shifts if classification is correlated with lineup changes."
      },
      {
        "code": "MULTIPLE_TESTING",
        "text": "There are many possible lineup pairs and many shot‑type categories; without adequate adjustment, inflated false‑positive rates are likely."
      },
      {
        "code": "SAMPLE_SIZE_POWER",
        "text": "Some lineups occur rarely, making direct head‑to‑head comparisons of specific five‑man units underpowered unless many such pairs are pooled."
      }
    ]
  },
  "prior_work": {
    "already_answered": "no",
    "cited": [
      "FAM:SF34",
      "FAM:SF-PAP-050",
      "FAM:SF-PAP-009"
    ],
    "summary": "No prior study explicitly tested whether a change in the offensive five leads to a detectable shift in shot mix. Evidence on opponent lineup adaptation (SF34), absence of a player (SF-PAP-050), and lineup coverage feasibility (SF-PAP-009) provides indirect, inconclusive signals. Several studies highlight the risks of confounding, label noise, and low measurement reliability in similar line‑up analyses."
  },
  "risks": [
    {
      "code": "CONFOUNDING",
      "text": "Lineup substitutions are non‑random and depend on game situation, which also affects shot selection; simple comparison of lineups will be confounded unless within‑game, within‑opponent controls are applied."
    },
    {
      "code": "LABEL_ERROR",
      "text": "Play types such as OTHER are known to be noisy; misclassification may attenuate effect sizes and reduce power, and could produce apparent shifts if error rates correlate with substitution patterns."
    },
    {
      "code": "MULTIPLE_TESTING",
      "text": "Testing many specific lineup pairs across many shot‑type categories without correction will yield false positives; a global test with appropriate multiplicity adjustment is needed."
    },
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "Comparisons of low‑possession lineups may be underpowered even with three seasons of data; the design requires either a pooled analysis or a minimum‑possession threshold."
    },
    {
      "code": "MEASURE_RELIABILITY",
      "text": "The split‑half reliability of play‑type shares for a given lineup may be low, as suggested by team‑level adaptation studies; this could make even true lineup effects hard to detect."
    },
    {
      "code": "RTM_SELECTION",
      "text": "If only extreme‑shot‑mix lineups are compared (e.g., after seeing a large difference), regression to the mean could create an illusion of convergence, or vice‑versa."
    }
  ],
  "predicted_outcome": {
    "supported": 0.60,
    "rejected": 0.05,
    "untestable": 0.05,
    "artifact": 0.10,
    "uncertain": 0.20
  },
  "decision": "proceed_with_changes",
  "design": {
    "estimand": "Difference in the multinomial distribution of play‑type shares between two offensive fives that differ by exactly one player, conditional on opponent lineup, score margin, period, and seconds remaining.",
    "unit": "Half‑court possession with a recorded shot attempt (play‑type categorisation), aggregated to a stint (e.g., a continuous segment of constant offensive and defensive fives).",
    "sample": "All regular‑ season and playoff games from NBA 2022‑23, 2023‑24, and 2024‑25. Restrict to non‑garbage‑time half‑court possessions (score margin ≤ 20 in Q1–Q3, ≤ 15 in Q4). Keep only offensive fives that have at least 30 possessions and defensive matchups where the opponent five is constant during the comparison window. Use within‑game, within‑opponent‑stint comparisons where two different offensive fives face the same opponent five and at least one possession is recorded for each.",
    "power": "Based on preliminary data, a 1 percentage‑point shift in a common shot‑type share (e.g., SPOT_UP) can likely be detected with 80% power using >50,000 comparison stints across three seasons, assuming a two‑sided α = 0.05 after Holm correction for up to eight play‑type categories.",
    "controls": "Fixed effects for opponent five, period, and game; linear and quadratic score margin; seconds remaining in the quarter; days of rest; home/away indicator.",
    "falsification": "Placebo 1: Compare the shot mix of the same offensive five in two non‑overlapping stints under identical opponent and game‑state conditions; difference should be non‑significant. Placebo 2: Randomly permute player identities within a lineup to show no systematic pattern. Placebo 3: Test pre‑substitution shot mix of the two fives before the change to check for parallel trends.",
    "multiplicity": "Primary analysis uses a global chi‑square test across all play types adjusted for lineup comparisons. Secondary analyses per play type are Holm‑corrected for the number of play‑type categories and the top‑level tests (e.g., 5 pair types × 8 categories).",
    "decision_rule": "Reject the null hypothesis of no lineup‑induced shift in shot mix if the global test yields p < 0.05 after multiplicity adjustment, and if all pre‑specified placebo tests are passed (p > 0.20). Secondary per‑type shifts are considered supporting evidence.",
    "data_version": "2026‑11‑02 snapshot of NBA stats API per‑game files (play‑by‑play, substitution intervals, starters, defensive matchups, box‑score) and Neo4j‑derived play‑type possession records."
  }
}

